impl Rule {
    /// What the rule carries from line to line.
    /// A rule that embeds a language carries that language's state, when its
    /// feature is on.
    /// A rule whose end repeats a begin capture group carries that group.
    #[inline]
    pub(crate) fn carried_state(self) -> rules::CarriedState {
        match self {
            Rule::IffalseBlock
            | Rule::Comment
            | Rule::CommentAt0
            | Rule::CommentAt1
            | Rule::Braces
            | Rule::Conditionals
            | Rule::MathContentAt0
            | Rule::MathContentAt6
            | Rule::Root => rules::CarriedState::None,
            Rule::DollarMath => rules::CarriedState::Backref(1),
            Rule::MathContentAt6At0 => rules::embedded!(R, "lang-r")
                .map_or(rules::CarriedState::None, rules::CarriedState::Embed),
        }
    }
}

impl Rule {
    /// The halt where the embedding rule's end matches, for the language it
    /// embeds.
    /// A rule that embeds nothing gets one the engine never asks for.
    pub(crate) fn end_halt(self) -> rules::FnHalt {
        match self {
            Rule::IffalseBlock
            | Rule::Comment
            | Rule::CommentAt0
            | Rule::CommentAt1
            | Rule::Braces
            | Rule::Conditionals
            | Rule::DollarMath
            | Rule::MathContentAt0
            | Rule::MathContentAt6
            | Rule::Root => super::engine::never,
            Rule::MathContentAt6At0 => super::engine::closes_brace,
        }
    }
}

