/// A regular expression of the grammar, which several patterns can share.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
#[repr(u16)]
pub(crate) enum Rx {
    /// `(?<=^\s*)((\\)iffalse)(?!\s*[{}]\s*\\fi\b)`.
    IffalseBlock,
    /// `((\\)(?:else|fi))\b`.
    IffalseBlockEnd,
    /// `(^[\t ]+)?(?=%)`.
    Comment,
    /// `(?!\G)`.
    CommentEnd,
    /// `%:?`.
    CommentAt0,
    /// `$\n?`.
    CommentAt0End,
    /// `^(%!TEX) (\S*) =`.
    CommentAt1,
    /// `(?<!\\)\{`.
    Braces,
    /// `(?<!\\)}`.
    BracesEnd,
    /// `(?<=^\s*)\\if(?!f\b)[a-z]*`.
    Conditionals,
    /// `(?<=^\s*)\\fi`.
    ConditionalsEnd,
    /// `…`.
    MacroControl,
    /// `((\\)catcode)'\\?.(=)(\d+)`.
    Catcode,
    /// `[]\[]`.
    RootAt4,
    /// `(\$\$?)`.
    DollarMath,
    /// `(\1)`.
    DollarMathEnd,
    /// `\\\$`.
    DollarMathAt0,
    /// `((\\)(?:text|mbox))(\{)`.
    MathContentAt0,
    /// `}`.
    MathContentAt0End,
    /// `\\\\`.
    RootAt6,
    /// `\\@ifnextchar[(\[{]`.
    Ifnextchar,
    /// `…`.
    MacroGeneralAt0,
    /// `…`.
    MacroGeneralAt1,
    /// `(\\)(?:[,;]|[@\p{Alphabetic}]+)`.
    MacroGeneralAt2,
    /// `(\\)[^@-Za-z]`.
    MacroGeneralAt3,
    /// `\\[{}]`.
    MathContentAt1,
    /// `…`.
    MathContentAt2,
    /// `…`.
    MathContentAt3,
    /// `…`.
    MathContentAt4,
    /// `…`.
    MathContentAt5,
    /// `((\\)Sexpr(\{))`.
    MathContentAt6,
    /// `(((})))`.
    MathContentAt6End,
    /// `\G(?!})`.
    MathContentAt6At0,
    /// `(?=})`.
    MathContentAt6At0End,
    /// `(\\)(?!begin\{|verb)([A-Za-z]+)`.
    MathContentAt7,
    /// `(?<!\\)\(`.
    MathContentAt10,
    /// `(?<!\\)\)`.
    MathContentAt11,
    /// `(([0-9]*\.[0-9]+)|[0-9]+)`.
    MathContentAt12,
    /// `[-*+/]|(?<!\^)\^(?!\^)|(?<!_)_(?!_)`.
    MathContentAt13,
}

